// Which of a group class's lesson rows were generated by the class schedule
// itself — and so may be deleted and regenerated when the class is edited on
// the Group Classes page.
//
// A class's rows also include sessions attached from the Lessons page ("Make
// Group" → pick an existing class) and occurrences a coach moved to another
// time. Those aren't the schedule's to rebuild: editing the class used to
// delete them along with everything else and never recreate them.

const DAYS = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"];

type ClassSchedule = {
  frequency: string;
  days_of_week?: string[] | null;
  start_date: string;
  end_date?: string | null;
  start_time?: string | null;
};

type LessonRow = {
  lesson_date: string | null;
  start_time?: string | null;
  is_recurring?: boolean | null;
  billing_status?: string | null;
};

function weekdayName(date: string) {
  const jsDay = new Date(`${date}T00:00:00`).getDay();
  return DAYS[jsDay === 0 ? 6 : jsDay - 1];
}

const sameTime = (a?: string | null, b?: string | null) => (a || "").slice(0, 5) === (b || "").slice(0, 5);

/**
 * True for an upcoming, unbilled row that the class schedule (as it was
 * before this edit) generated. Matching is by weekday/range/time rather than
 * exact dates on purpose: biweekly classes re-anchor their alternating weeks
 * on the date of each edit, so recomputing exact past occurrences would miss
 * rows.
 */
export function isRegeneratableScheduleLesson(row: LessonRow, schedule: ClassSchedule, today: string) {
  const date = row.lesson_date;
  if (!date || date < today) return false;
  if ((row.billing_status || "unbilled") !== "unbilled") return false;
  if (!sameTime(row.start_time, schedule.start_time)) return false;

  if (schedule.frequency === "once") {
    return date === schedule.start_date;
  }

  return (
    !!row.is_recurring &&
    date >= schedule.start_date &&
    (!schedule.end_date || date <= schedule.end_date) &&
    (schedule.days_of_week || []).includes(weekdayName(date))
  );
}
